import{_ as e,o as t,c as o,a0 as l}from"./chunks/framework.BpIFOypQ.js";const p=JSON.parse('{"title":"使用说明","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":null}'),i={name:"guide.md"};function r(d,a,s,n,c,h){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h1><p>LV Box 在浏览器里直接与手机通信，不需要安装客户端。</p><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><ul><li>支持 WebUSB 的 Chrome、Edge 等 Chromium 内核浏览器</li><li>手机开启开发者选项与 USB 调试，使用可传输数据的 USB 线</li><li>通过 HTTPS 或 <code>localhost</code> 打开本站</li></ul><h2 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to &quot;连接&quot;">​</a></h2><p>点击「选择设备」，在弹出的系统窗口中选中手机，然后允许调试授权。首次连接会在浏览器中生成一对密钥，之后同一台电脑可直接复用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>功能是否生效取决于设备的 Android 版本、厂商 ROM 与 ADB Shell 权限。部分系统信息在受限设备上读不到；进入 Fastboot 的操作只发送重启命令，不提供刷机。</p><div class="warning custom-block"><p class="custom-block-title">提醒</p><p>玩机操作有风险，请确认了解每一步的后果再执行。</p></div>',9)])])}const _=e(i,[["render",r]]);export{p as __pageData,_ as default};
